// js
const exit = ctx.entry.effective_range.to;
const site = get(ctx.entry.employee_extension_data, 'worksite', '');
const contracts = ctx.reads.employee_contract;
const on = (row, key) => get(row, key, null);
const siteOf = (row) => get(row.employee_extension_data, 'worksite', '');
const ground = (row) => get(row.employee_extension_data, 'exit_ground', 'OTHER');
const leavers = contracts.filter(
	(row) =>
		row.status === 'SEALED' &&
		ctx.lookup.grounds.includes(ground(row)) &&
		get(row.employee_extension_data, 'fixed_term', false) !== true &&
		on(row, 'effective_range.to') != null &&
		on(row, 'effective_range.to') >= add_days(exit, -ctx.lookup.window_days) &&
		on(row, 'effective_range.to') <= exit
);
const staff = contracts.filter(
	(row) =>
		row.status === 'SEALED' &&
		on(row, 'effective_range.from') <= exit &&
		(on(row, 'effective_range.to') == null || on(row, 'effective_range.to') >= exit)
);
const siteStaff = staff.filter((row) => siteOf(row) === site).length;
const siteLeavers = leavers.filter((row) => siteOf(row) === site);
const siteDay = siteLeavers.filter((row) => on(row, 'effective_range.to') === exit).length;
const rolling =
	siteStaff < ctx.lookup.small_site_upper
		? ctx.lookup.small_site_count
		: siteStaff < ctx.lookup.medium_site_upper
			? Math.floor(siteStaff / ctx.lookup.medium_site_divisor)
			: siteStaff < ctx.lookup.large_site_upper
				? Math.floor(siteStaff / ctx.lookup.large_site_divisor)
				: Math.floor(siteStaff / ctx.lookup.largest_site_divisor);
const daily =
	siteStaff < ctx.lookup.medium_site_upper
		? ctx.lookup.medium_site_daily
		: siteStaff < ctx.lookup.large_site_upper
			? ctx.lookup.large_site_daily
			: ctx.lookup.largest_site_daily;
const siteHit =
	siteLeavers.length > rolling ||
	(siteStaff >= ctx.lookup.small_site_upper && siteDay > daily);
const entityDay = leavers.filter((row) => on(row, 'effective_range.to') === exit).length;
return siteHit || leavers.length > ctx.lookup.entity_rolling || entityDay > ctx.lookup.entity_daily;

