condition:
// js
const versions = ctx.reads.entity_profile_version;
const from = ctx.entry.effective_range.from;
const earlier = versions.filter(
	(version) => version.id !== ctx.entry.id && get(version, 'effective_range.from', '') < from
);
const previous = earlier.filter(
	(version) =>
		!earlier.some(
			(other) =>
				other.id !== version.id &&
				get(other, 'effective_range.from', '') > get(version, 'effective_range.from', '')
		)
);
return (
	previous.length === 1 &&
	(get(previous[0], 'name', null) !== get(ctx.entry, 'name', null) ||
		get(previous[0], 'registered_address', null) !== get(ctx.entry, 'registered_address', null) ||
		get(previous[0], 'representative_name', null) !== get(ctx.entry, 'representative_name', null))
);

